// SPDX-License-Identifier: MIT
pragma solidity 0.6.12;
pragma experimental ABIEncoderV2;

import "forge-std/Test.sol";
import "../src/KAKASHISENSEI.sol";

contract KakashiSenseiTest is Test {
    KAKASHISENSEI token;
    address owner = address(0x1);
    address alice = address(0x2);
    address bob = address(0x3);
    address mockRouter = address(0x10ED43C718714eb63d5aA57B78B54704E256024E);
    address mockFactory = address(0x1234567890123456789012345678901234567890);
    address mockPair = address(0xABC);
    address BUSD = 0xe9e7CEA3DedcA5984780Bafc599bD69ADd087D56;

    function setUp() public {
        // Mock Uniswap router and factory calls
        vm.mockCall(
            mockRouter, 
            abi.encodeWithSignature("factory()"), 
            abi.encode(mockFactory)
        );
        vm.mockCall(
            mockFactory, 
            abi.encodeWithSignature("createPair(address,address)"),
            abi.encode(mockPair)
        );

        // Deploy token and fund test addresses
        vm.startPrank(owner);
        token = new KAKASHISENSEI();
        token.transfer(alice, 1000 * 10**uint256(token.decimals()));
        vm.stopPrank();
    }

    function testMaxTxStopTransactions() public {
        // Prevent antibot interference and set tx limit to 0%
        vm.startPrank(owner);
        token.turnOffAntibotMode();
        token.setMaxTxPercent(0);
        vm.stopPrank();

        // Verify users can't transfer any tokens
        uint256 amount = 1 * 10**uint256(token.decimals());
        vm.prank(alice);
        vm.expectRevert("Transfer amount exceeds the maxTxAmount.");
        token.transfer(bob, amount);
    }

    function testAntibotModeBlocksTransactions() public {
        // Antibot mode is enabled by default
        uint256 amount = 1 * 10**uint256(token.decimals());

        // Non-whitelisted transfers should fail
        vm.prank(alice);
        vm.expectRevert("Address not in antibot mode whitelist");
        token.transfer(bob, amount);

        // Should allow owner transfers
        uint256 ownerBalance = token.balanceOf(owner);
        uint256 bobBalance = token.balanceOf(bob);
        vm.prank(owner);
        token.transfer(bob, amount);

        assertEq(token.balanceOf(owner), ownerBalance - amount, "Owner balance should decrease");
        assertEq(token.balanceOf(bob), bobBalance + amount, "Bob should receive tokens from owner");
    }

    function testWhitelistedTransferBypass() public {
        // Whitelist test addresses
        address[] memory whitelist = new address[](2);
        whitelist[0] = alice;
        whitelist[1] = bob;
        address[] memory empty = new address[](0);

        vm.prank(owner);
        token.setAntibotModeWhitelist(whitelist, empty);

        // Verify successful transfer
        uint256 amount = 1 * 10**uint256(token.decimals());
        uint256 initialBalance = token.balanceOf(bob);
        vm.prank(alice);
        token.transfer(bob, amount);
        assertEq(token.balanceOf(bob), initialBalance + amount, "Bob should receive tokens from Alice");
    }

    function testOwnerAntibotDisable() public {
        // Permanently disable antibot protection
        vm.prank(owner);
        token.turnOffAntibotMode();

        // Verify transfers work normally
        uint256 amount = 1 * 10**uint256(token.decimals());
        uint256 initialBalance = token.balanceOf(bob);
        vm.prank(alice);
        token.transfer(bob, amount);
        assertEq(token.balanceOf(bob), initialBalance + amount, "Bob should receive tokens after antibot disable");
    }

    function testNonAdminAccessControl() public {
        // Verify non-owners can't modify key protections
        vm.prank(alice);
        vm.expectRevert("Ownable: caller is not the owner");
        address[] memory empty = new address[](0);
        token.setAntibotModeWhitelist(empty, empty);

        vm.prank(alice);
        vm.expectRevert("Ownable: caller is not the owner");
        token.setMaxTxPercent(10);

        vm.prank(alice);
        vm.expectRevert("Ownable: caller is not the owner");
        token.turnOffAntibotMode();
    }
}
